{"sql": "-- Use a different approach for year_numbers
WITH year_numbers AS (
    SELECT CAST(n AS INTEGER) AS year_num
    FROM generate_series(1, 20) AS n
)
SELECT * FROM year_numbers"}

{"sql": "-- Try UNNEST approach
WITH year_numbers AS (
    SELECT CAST(value AS INTEGER) AS year_num
    FROM UNNEST(generate_series(1, 20)) AS t(value)
)
SELECT * FROM year_numbers"}
